 const activeData=viewerStudent?viewerDataForStudent(data,viewerStudent):data,targets=viewerStudent?studentTargets(data,viewerStudent.id):allTargets(data),due=targets.filter(x=>!x.state.is_completed&&x.state.next_review_date&&x.state.next_review_date<=today()),scheduledCount=activeData.profile?.id?scheduledTargetsForUser(activeData,today(),activeData.profile.id).length:scheduledTargets(activeData,today()).length,cafeStockoutCount=0,role=(viewerStudent?"student":data.profile?.role||"none")as UserRole,roleNav=role==="teacher"?["students","生徒",Users]as[View,string,React.ElementType]:role==="student"?["assignments","課題",ClipboardList]as[View,string,React.ElementType]:null;
