 const activeSave=viewerStudent?saveAsViewer:save;
 const openViewer=(student:Profile)=>{const linked=data.teacherLinks.some(l=>l.teacher_id===data.profile?.id&&l.student_id===student.id&&l.status==="active");if(!linked){flash("連携済みの生徒だけ表示できます");return}if(!confirm("この生徒の画面に移動しますか？"))return;setSelectedTeacherStudent(student);setViewerStudent(student);setView("home");setDetail(null);setStudy(null);setHistory(null)};
 const closeViewer=()=>{try{localStorage.removeItem("recaloop-viewer")}catch{}const student=viewerStudent;setViewerStudent(null);if(student)setSelectedTeacherStudent(student);setView("students");setDetail(null);setStudy(null);setHistory(null)};
