 const openDeck=async(type:TargetType,id:string)=>{setLoadingDeck("デッキを準備しています");const started=performance.now();try{if(type==="material"){const deck=data.materialDecks.find(item=>item.id===id),current=data.materialNodes.filter(n=>n.deck_id===id),expected=deck?.item_count||0,loaded=current.filter(n=>n.node_type==="item").length,cacheHit=expected>0&&loaded>=expected;if(!cacheHit){const nodes=await loadMaterialNodes(id),count=nodes.filter(n=>n.node_type==="item").length;setData(currentData=>currentData?{...currentData,materialNodes:[...currentData.materialNodes.filter(n=>n.deck_id!==id),...nodes],materialDecks:currentData.materialDecks.map(item=>item.id===id?{...item,item_count:count}:item)}:currentData);console.info("Deck detail load",{type,id,ms:Math.round(performance.now()-started),requests:1,count,cache:false})}else console.info("Deck detail load",{type,id,ms:Math.round(performance.now()-started),requests:0,count:loaded,cache:true})}else{const list=data.wordLists.find(item=>item.id===id),current=data.wordCards.filter(card=>card.list_id===id),expected=list?.item_count||0,cacheHit=expected>0&&current.length>=expected;if(!cacheHit){const cards=await loadWordCards(id);setData(currentData=>currentData?{...currentData,wordCards:[...currentData.wordCards.filter(card=>card.list_id!==id),...cards],wordLists:currentData.wordLists.map(item=>item.id===id?{...item,item_count:cards.length}:item)}:currentData);console.info("Deck detail load",{type,id,ms:Math.round(performance.now()-started),requests:1,count:cards.length,cache:false})}else console.info("Deck detail load",{type,id,ms:Math.round(performance.now()-started),requests:0,count:current.length,cache:true})}setDetail({type,id})}catch(e){console.error("Deck detail load failed",e);flash(e instanceof Error?`デッキ詳細を読み込めませんでした: ${e.message}`:"デッキ詳細を読み込めませんでした")}finally{setLoadingDeck("")}};
