function AppTopBar({navigate,active}:{navigate:(view:View)=>void;active:View}){if(active!=="home")return null;return <header className="app-topbar"><span/><div className="topbar-actions"><button onClick={()=>navigate("notices")} aria-label="お知らせ"><Bell size={20}/></button><button onClick={()=>navigate("settings")} aria-label="設定"><Settings size={20}/></button></div></header>}
