function confirmRecaloopExport(summary:{title:string;cardCount:number;imageCount:number;audioCount:number;mediaCount:number;missingMedia:string[];fileName:string}){if(summary.missingMedia.length){alert(`メディア参照切れがあるため書き出せません。\n不足: ${summary.missingMedia.length}件`);return null}const input=prompt(`「${summary.title}」を書き出します\n\nカード：${summary.cardCount}枚\n画像：${summary.imageCount}件\n音声：${summary.audioCount}件\n合計メディア：${summary.mediaCount}件\n\nファイル名を確認してください。`,summary.fileName);return input?recaloopFileName(input):null}
function normalizeDeckTitle(value:string){return cleanCardText(value).replace(/\s+/g," ").trim().toLowerCase()}
function uniqueDeckTitle(title:string,lists:WordList[],ownerId:string){const used=new Set(lists.filter(list=>list.user_id===ownerId&&!list.deleted_at).map(list=>normalizeDeckTitle(list.title)));if(!used.has(normalizeDeckTitle(title)))return title;for(let index=2;;index++){const candidate=`${title}（${index}）`;if(!used.has(normalizeDeckTitle(candidate)))return candidate}}
function cardLearningKey(card:Pick<WordCard,"memo"|"card_id"|"order_index">){const path=compactCrumbs([card.memo]).join("/"),number=cleanCardText(card.card_id||"");return path||number?`${path}\u0000${number}`:`order:${card.order_index}`}
function sameStructureCards(current:WordCard[],incoming:Pick<WordCard,"memo"|"card_id"|"order_index">[]){if(!current.length||current.length!==incoming.length)return false;const counts=new Map<string,number>();current.forEach(card=>counts.set(cardLearningKey(card),(counts.get(cardLearningKey(card))||0)+1));for(const card of incoming){const key=cardLearningKey(card),count=counts.get(key)||0;if(!count)return false;if(count===1)counts.delete(key);else counts.set(key,count-1)}return counts.size===0}
