function MaterialTree({nodes,data,setData,history,study,save,selectMode=false,selected=[],setSelected,visibleIds}:{nodes:MaterialNode[];data:AppData;setData:(d:AppData)=>void;history:(t:ReviewTarget)=>void;study:(t:ReviewTarget[])=>void;save:(t:ReviewTarget,r:Rating|null,u:boolean)=>Promise<void>;selectMode?:boolean;selected?:string[];setSelected?:(ids:string[])=>void;visibleIds?:Set<string>}){return <div className="space-y-3 mt-4">{sortNodes(nodes.filter(n=>!n.parent_id)).map(n=><MaterialBranch key={n.id} node={n} nodes={nodes} data={data} setData={setData} history={history} study={study} save={save} selectMode={selectMode} selected={selected} setSelected={setSelected} visibleIds={visibleIds}/>)}</div>}
