async function importRecaloopDeck(file:File,data:AppData,setData:(d:AppData)=>void,flash:(s:string)=>void,onProgress?:(progress:RecaloopImportProgress)=>void){
 const ownerId=data.profile?.id;
 if(!ownerId)throw new Error("ログイン中のユーザー情報を取得できません。");
 const imported=await importWordDeckPackage(file,{onProgress,shouldSkip:deck=>{const splitPart=/\bpart\s+\d+\/\d+\b/i.test(deck.description||"");return !splitPart&&data.wordLists.some(l=>l.user_id===ownerId&&!l.deleted_at&&normalizeDeckTitle(l.title)===normalizeDeckTitle(deck.title||"読み込みデッキ")&&l.external_version===(deck.version||deck.updatedAt||"1.0.0"))}}),version=imported.deck.version||imported.deck.updatedAt||"1.0.0",title=imported.deck.title||"読み込みデッキ",splitPart=/\bpart\s+\d+\/\d+\b/i.test(imported.deck.description||"");
 const latest=data.wordLists.find(l=>l.user_id===ownerId&&!l.deleted_at&&normalizeDeckTitle(l.title)===normalizeDeckTitle(title)&&l.external_version===version);
 if(latest){flash(`「${latest.title}」は既に最新です（${imported.stats.elapsedMs}ms）`);return}
 const sameName=data.wordLists.find(l=>l.user_id===ownerId&&!l.deleted_at&&normalizeDeckTitle(l.title)===normalizeDeckTitle(title));
 let existing:WordList|undefined,current:WordCard[]=[];
 if(sameName&&splitPart){
  existing=sameName;
 }else if(sameName){
  current=await loadWordCards(sameName.id);
  const structureMatch=sameStructureCards(current,imported.cards);
  if(structureMatch){
   existing=confirm(`同じ名前のデッキ「${sameName.title}」があります。\n\n章・問題番号の構造が一致しています。\n学習履歴を残してこのデッキを上書き更新しますか？\n\nOK: 上書き更新\nキャンセル: どちらも残す`)?sameName:undefined;
  }else{
   existing=confirm(`同じ名前のデッキ「${sameName.title}」があります。\n\n章・問題番号の完全一致は確認できませんでした。\n\nOK: それでも上書き更新\nキャンセル: どちらも残す`)?sameName:undefined;
  }
 }
 if(!existing)current=[];
 const targetTitle=existing?title:uniqueDeckTitle(title,data.wordLists,ownerId),targetList=existing||await createWordList({title:targetTitle,subject:null,description:imported.deck.description||null});
 await updateWordList(targetList.id,{title:targetTitle,description:imported.deck.description||targetList.description,external_deck_id:null,external_version:version,review_mode:imported.deck.reviewMode||"default"});
 if(existing&&!current.length)current=await loadWordCards(targetList.id);
 const byLearningKey=new Map(current.map(c=>[cardLearningKey(c),c])),byFingerprint=new Map(current.map(c=>[`${cleanCardText(c.front)}\u0000${cleanCardText(c.back)}\u0000${c.order_index}`,c])),used=new Set<string>(),newCards=[] as WordCard[];
 for(const card of imported.cards){
  const fingerprint=`${cleanCardText(card.front)}\u0000${cleanCardText(card.back)}\u0000${card.order_index}`,candidates=[byLearningKey.get(cardLearningKey(card)),byFingerprint.get(fingerprint)].filter(Boolean)as WordCard[],match=candidates.find(candidate=>!used.has(candidate.id));
  if(match){used.add(match.id);await updateWordCard(match.id,{card_id:card.card_id||match.card_id,front:card.front,back:card.back,memo:card.memo||null,order_index:card.order_index,front_media_ids:card.front_media_ids,back_media_ids:card.back_media_ids})}
  else newCards.push({id:crypto.randomUUID(),list_id:targetList.id,card_id:card.card_id||null,front:card.front,back:card.back,memo:card.memo||null,order_index:card.order_index,front_media_ids:card.front_media_ids,back_media_ids:card.back_media_ids,created_at:new Date().toISOString()});
 }
 const cardSaveStart=performance.now(),saved=newCards.length?await importWordCards(targetList.id,newCards):[];
 console.info(`カード保存 ${Math.round(performance.now()-cardSaveStart)}ms`);
 for(let i=0;i<saved.length;i++)await updateWordCard(saved[i].id,{front_media_ids:newCards[i]?.front_media_ids||[],back_media_ids:newCards[i]?.back_media_ids||[]});
 setData(await loadAppData());
 const message=`${imported.stats.cardCount}枚のカード ・ 画像${imported.stats.imageCount}件 ・ 音声${imported.stats.audioCount}件 ・ ${(imported.stats.elapsedMs/1000).toFixed(2)}秒`;
 flash(existing?`.recaloopで既存デッキを更新しました（${message}）`:`.recaloopを読み込みました（${message}）`);
}

