type SelectEntry={key:string;target:ReviewTarget};
type SelectTreeNode={children:Map<string,SelectTreeNode>;items:SelectEntry[]};
function SelectableTargetTree({entries,selected,setSelected,emptyText="対象がありません。"}:{entries:SelectEntry[];selected:string[];setSelected:(ids:string[])=>void;emptyText?:string}){const[query,setQuery]=useState(""),needle=query.trim().toLowerCase();const filtered=entries.filter(entry=>`${entry.target.group_title} ${entry.target.context||""} ${entry.target.title} ${entry.target.card_id||""} ${entry.target.back||""}`.toLowerCase().includes(needle)),root:SelectTreeNode={children:new Map(),items:[]},used=new Set<number>();sortTargetsGlobal(filtered.map(e=>e.target)).forEach(target=>{const index=filtered.findIndex((entry,i)=>!used.has(i)&&entry.target.id===target.id&&entry.target.target_type===target.target_type);if(index<0)return;used.add(index);const entry=filtered[index],parts=targetSelectionCrumbs(target);let node=root;parts.forEach(part=>{if(!node.children.has(part))node.children.set(part,{children:new Map(),items:[]});node=node.children.get(part)!});node.items.push(entry)});const visibleKeys=[...new Set(filtered.map(entry=>entry.key))],toggleKeys=(keys:string[],checked:boolean)=>setSelected(checked?[...new Set([...selected,...keys])]:selected.filter(id=>!keys.includes(id)));const render=(node:SelectTreeNode,path:string[]):React.ReactNode=><>{sortedTreeEntries(node.children.entries()).map(([label,child])=>{const keys=selectTreeKeys(child),selectedCount=keys.filter(id=>selected.includes(id)).length,checked=keys.length>0&&selectedCount===keys.length,partial=selectedCount>0&&selectedCount<keys.length;return <StoredDetails key={[...path,label].join("/")} storageKey={`recaloop-select-tree-${[...path,label].join("/")}`} className={`surface select-tree-branch ${checked?"selected":partial?"partial":""}`} summary={<summary className="select-tree-summary"><span className="tree-open-hint">▶</span><button type="button" className="select-tree-summary-main" onClick={e=>{e.preventDefault();e.stopPropagation();toggleKeys(keys,!checked)}}><span>{label}</span><b>{selectedCount}/{keys.length}</b></button></summary>}><div className="select-tree-children">{render(child,[...path,label])}</div></StoredDetails>})}{node.items.map(entry=>{const checked=selected.includes(entry.key);return <button type="button" key={entry.key} className={`select-tree-item ${checked?"selected":""}`} onClick={()=>toggleKeys([entry.key],!checked)}><span>{entry.target.title}{entry.target.back&&` / ${entry.target.back}`}</span></button>})}</>;return <div className="select-tree"><div className="deck-search"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="カードを検索"/></div><div className="select-tree-actions"><button className="quiet-button" disabled={!visibleKeys.length} onClick={()=>toggleKeys(visibleKeys,true)}>すべて選択</button><button className="quiet-button" disabled={!selected.length} onClick={()=>toggleKeys(visibleKeys,false)}>すべて解除</button><span>{selected.length}件選択中</span></div><div className="select-tree-list">{filtered.length?render(root,[]):<p className="text-sm text-[#718398]">{emptyText}</p>}</div></div>}
function selectTreeKeys(node:SelectTreeNode):string[]{return[...node.items.map(i=>i.key),...[...node.children.values()].flatMap(selectTreeKeys)]}
function mediaIdVariants(id:string){const match=id.match(/^(recaloop:[^:]+:)(.+)$/);if(!match)return[id];const prefix=match[1],raw=match[2],variants=new Set<string>([id]);try{variants.add(`${prefix}${decodeURIComponent(raw).normalize("NFC")}`)}catch{}const fileName=mediaFileNameFromRef(raw);variants.add(`${prefix}${fileName}`);variants.add(`${prefix}${encodeURIComponent(fileName).replace(/%2F/gi,"/")}`);variants.add(`${prefix}${raw.trim().replace(/^media\//i,"").normalize("NFC")}`);variants.add(`${prefix}${encodeURIComponent(raw).replace(/%2F/gi,"/")}`);return[...variants]}
const mediaUrlCache=new Map<string,{url:string;record:{kind:"image"|"audio";fileName:string};refs:number;timer?:ReturnType<typeof setTimeout>}>();
async function acquireLocalMediaUrlAny(id:string){for(const candidate of mediaIdVariants(id)){const cached=mediaUrlCache.get(candidate);if(cached){if(cached.timer)clearTimeout(cached.timer);cached.refs++;return{cacheKey:candidate,url:cached.url,record:cached.record}}const media=await localMediaUrl(candidate);if(media){mediaUrlCache.set(candidate,{url:media.url,record:{kind:media.record.kind,fileName:media.record.fileName},refs:1});return{cacheKey:candidate,url:media.url,record:{kind:media.record.kind,fileName:media.record.fileName}}}}return null}
