function compactCrumbs(parts:(string|undefined|null)[]){const out:string[]=[];parts.flatMap(part=>(part||"").split(/\s*\/+\s*/)).map(part=>cleanCardText(part).replace(/^\/+|\/+$/g,"").trim()).filter(part=>part&&part!=="/").forEach(part=>{if(out[out.length-1]!==part)out.push(part)});return out}
