function SettingsFormRow({label,children}:{label:string;children:React.ReactNode}){return <label className="settings-form-row no-icon"><b>{label}</b><div>{children}</div></label>}
function SettingsGroup({title,action,children}:{title?:string;action?:React.ReactNode;children:React.ReactNode}){return <section className="settings-group">{(title||action)&&<div className="settings-group-heading">{action}<h2>{title}</h2><span/> </div>}<div className="settings-group-card">{children}</div></section>}
