function ThemeColorPicker({title,value,options,onChange}:{title:string;value:string;options:readonly (readonly [string,string])[];onChange:(color:string)=>void}){return <div className="theme-color-picker"><p>{title}</p><div>{options.map(([label,color])=><button key={color} onClick={()=>onChange(color)} className={value===color?"active":""}><i style={{background:color}}/>{label}{value===color&&<Check size={16}/>}</button>)}</div></div>}
function LocalStoragePanel({data,flash}:{data:AppData;flash:(s:string)=>void}){const[items,setItems]=useState<{id:string;name:string;kind:string;size:number;used:boolean}[]>([]),[loading,setLoading]=useState(false);const refresh=useCallback(async()=>{setLoading(true);try{const active=activeMediaIds(data),records=await listLocalMedia();setItems(records.map(record=>({id:record.id,name:record.fileName,kind:record.kind,size:record.size,used:active.has(record.id)})).sort((a,b)=>b.size-a.size))}catch(e){console.error("local media usage load failed",e);flash("ローカル容量を取得できませんでした")}finally{setLoading(false)}},[data,flash]);useEffect(()=>{void refresh()},[refresh]);const total=items.reduce((sum,item)=>sum+item.size,0),unused=items.filter(item=>!item.used),unusedSize=unused.reduce((sum,item)=>sum+item.size,0);const clearUnused=async()=>{if(!unused.length)return;if(!confirm("未使用メディア "+unused.length+"件（"+bytesLabel(unusedSize)+"）を削除しますか？"))return;await deleteLocalMedia(unused.map(item=>item.id));await refresh();flash("未使用メディアを削除しました")};return <SettingsGroup title="データとストレージ"><SettingsFormRow label="端末内メディア"><span className="settings-value">{bytesLabel(total)}</span></SettingsFormRow><SettingsFormRow label="未使用"><span className="settings-value">{bytesLabel(unusedSize)} ・ {unused.length}件</span></SettingsFormRow><div className="settings-button-row"><button className="secondary-button" onClick={refresh} disabled={loading}>{loading?"確認中...":"再計算"}</button></div><div className="settings-button-row"><button className="secondary-button danger-button" onClick={clearUnused} disabled={!unused.length}>未使用をクリア</button></div>{items.slice(0,6).map(item=><div className="settings-storage-row" key={item.id}><span>{item.used?"使用中":"未使用"}</span><b>{item.name}</b><em>{bytesLabel(item.size)}</em></div>)}</SettingsGroup>}
function ViewerSettings({student}:{student:Profile}){return <><PageTitle title="設定" sub={`${student.display_name||"生徒"}さんのプロフィール`}/><div className="card settings-card max-w-xl mt-5"><div><span className="text-xs text-[#718398] font-bold">ニックネーム</span><b className="block mt-1">{student.display_name||"未設定"}</b></div><div><span className="text-xs text-[#718398] font-bold">年代</span><b className="block mt-1">{student.age_group||ageGroupFromGrade(student.grade_level)||"未設定"}</b></div><div><span className="text-xs text-[#718398] font-bold">学年</span><b className="block mt-1">{student.grade_level||"未設定"}</b></div><div><span className="text-xs text-[#718398] font-bold">志望校</span><b className="block mt-1">{student.target_school||"未定"}</b></div><p className="notice">viewer modeでは、生徒の学習画面を先生権限で確認しています。プロフィール編集は生徒本人の設定画面から行います。</p></div></>}

function DateInput({value,onChange,className=""}:{value:string;onChange:(value:string)=>void;className?:string}){return <span className={`date-input-wrap ${className}`}><input className="field form-date-input" type="date" value={value} onChange={e=>onChange(e.target.value)}/></span>}
function ReviewRulePanel({rule,save}:{rule:ReviewRuleFields&{review_mode?: "default"|"light"|null};save:(input:ReviewRuleFields&{review_mode?: "default"|"light"})=>Promise<void>}){
 const[mode,setMode]=useState<"default"|"light">(rule.review_mode||"default"),[busy,setBusy]=useState(false);
 const config=mode==="light"?{steps:"30秒 → 10分",intervals:[1,3,7,14,30,60],label:"短いステップで気軽に回す"}:{steps:"3分 → 30分",intervals:[1,3,7,14,30,60],label:"標準設定"};
 const submit=async()=>{setBusy(true);try{await save({review_mode:mode,max_reviews:null,review_intervals:config.intervals,reset_again_to_first:true})}finally{setBusy(false)}};
 return <details className="surface review-rule-panel"><summary>復習ルール</summary><div className="review-rule-grid"><label>モード<select className="field select-field" value={mode} onChange={e=>setMode(e.target.value as "default"|"light")}><option value="default">デフォルト</option><option value="light">ライト</option></select></label><div className="review-rule-check"><span><b>{config.label}</b><br/>習得ステップ: {config.steps}<br/>最初の復習間隔: 正解 1日 / 簡単 4日</span></div></div><p className="review-rule-help">回答ボタンは「もう一度 / 難しい / 正解 / 簡単」です。現在のDBは日付ベースで復習予定を保存するため、分単位ステップは学習モードの目安として扱い、復習日は既存の安全な日単位ルールで同期します。</p><button className="secondary-button mt-3" disabled={busy} onClick={submit}>{busy?"保存中...":"復習ルールを保存"}</button></details>
}
function RatingEditor({draft,currentUnknown,setDraft,save,label="保存"}:{draft:Draft;currentUnknown:boolean;setDraft:(d:Draft)=>void;save:()=>Promise<void>|void;label?:string}){const changed=Boolean(draft.rating)||draft.unknown!==currentUnknown,[busy,setBusy]=useState(false),[error,setError]=useState("");const run=async()=>{if(!changed||busy)return;setBusy(true);setError("");try{await save()}catch(e){const message=e instanceof Error?e.message:"保存に失敗しました";console.error("review save failed",e);setError(message)}finally{setBusy(false)}};return <div className="mt-4"><div className="rating-grid">{(Object.keys(ratings)as Rating[]).map(r=><button key={r} disabled={busy} onClick={()=>setDraft({...draft,rating:draft.rating===r?null:r})} className={`rating-button ${draft.rating===r?"selected":""}`}>{ratings[r].label}</button>)}</div><div className="flex justify-between items-center mt-3"><button type="button" disabled={busy} aria-pressed={draft.unknown} onClick={()=>setDraft({...draft,unknown:!draft.unknown})} className={`check-toggle ${draft.unknown?"active":""}`}><Bookmark size={16} fill={draft.unknown?"currentColor":"none"}/>チェック</button><button disabled={!changed||busy} onClick={run} className="save-button">{busy?"保存中...":label}</button></div>{error&&<p className="notice mt-3">{error}</p>}</div>}
function EditableTitle({title,save}:{title:string;save:(t:string)=>Promise<void>}){const[t,setT]=useState(title);return <div className="surface p-4 flex flex-col md:flex-row gap-2 mt-5"><input className="field flex-1" value={t} onChange={e=>setT(e.target.value)} aria-label="タイトル"/><button onClick={()=>save(t)} className="secondary-button">タイトルを保存</button></div>}
