function StateLine({state}:{state:ReviewState}){return <p className="text-[10px] text-[#718398] mt-1">評価 {state.last_rating||"未評価"} ・ 復習 {state.review_count}回 {state.next_review_date&&`・次回 ${state.next_review_date}`}</p>}
function PageTitle({title,action}:{title:string;sub:string;action?:React.ReactNode}){return <header className="page-header"><button type="button" onClick={()=>window.dispatchEvent(new Event("recaloop-back"))} aria-label="戻る">‹</button><h1>{title}</h1><div>{action}</div></header>}
function activeMediaIds(data:AppData){const ids=new Set<string>();data.wordCards.forEach(card=>{(card.front_media_ids||[]).forEach(id=>ids.add(id));(card.back_media_ids||[]).forEach(id=>ids.add(id));const list=data.wordLists.find(item=>item.id===card.list_id);if(list){mediaIdsFromText(card.front,list).forEach(id=>ids.add(id));mediaIdsFromText(card.back,list).forEach(id=>ids.add(id))}});return ids}
function bytesLabel(bytes:number){if(bytes<1024)return`${bytes} B`;const units=["KB","MB","GB"];let value=bytes/1024,index=0;while(value>=1024&&index<units.length-1){value/=1024;index++}return`${value>=10?value.toFixed(1):value.toFixed(2)} ${units[index]}`}
function Metric({label,value}:{label:string;value:string|number}){return <div className="rounded-xl bg-white/70 p-3 text-center"><b className="block text-lg">{value}</b><span className="text-[10px] text-[#718398]">{label}</span></div>}
function navActive(view:View,id:View){return view===id||(id==="study"&&["materials","decks","reviews","assignments"].includes(view))}
function BottomNav({view,navigate,badges={}}:{view:View;navigate:(view:View)=>void;badges?:Partial<Record<View,number>>}){return <nav className="bottom-nav" aria-label="メインメニュー">{baseNav.map(([id,label,Icon])=>{const count=badges[id]||0;return <button key={id} onClick={()=>navigate(id)} aria-label={label} title={label} aria-current={navActive(view,id)?"page" : undefined} className={navActive(view,id)?"active":""}><span className="nav-icon-wrap"><Icon size={22}/>{count>0&&<i className={`nav-badge ${id==="cafe"?"danger":""}`}>{count>99?"99+":count}</i>}</span><span>{label}</span></button>})}</nav>}
function materialTarget(n:MaterialNode,data:AppData):ReviewTarget{const d=data.materialDecks.find(x=>x.id===n.deck_id)!,context=materialContext(n,data.materialNodes);return{id:n.id,target_type:"material",group_id:d.id,group_title:d.title,context,title:n.title,memo:n.memo,state:n.state||empty}}
function cleanCardText(value?:string|null){return (value||"").replace(/\[([^\]]+\.(?:png|jpe?g|webp|gif|mp3|m4a|wav|ogg))\]/gi,"").replace(/[;:](none|null|undefined)$/i,"").trim().replace(/^(none|null|undefined)$/i,"")}
function mediaFileNameFromRef(value:string){const cleaned=value.trim().replace(/\\/g,"/").replace(/^\.?\//,"").replace(/^media\//i,"");let decoded=cleaned;try{decoded=decodeURIComponent(cleaned).normalize("NFC")}catch{decoded=cleaned.normalize("NFC")}const parts=decoded.split("/").filter(Boolean);return parts.at(-1)||decoded}
function mediaIdsFromText(value:string|undefined|null,list:WordList){const deckId=list.external_deck_id||list.source_content_id||list.id;return[...(value||"").matchAll(/\[([^\]]+\.(?:png|jpe?g|webp|gif|mp3|m4a|wav|ogg))\]/gi)].map(match=>`recaloop:${deckId}:${mediaFileNameFromRef(match[1])}`)}
function fallbackCardText(problem:string|null|undefined,front:string){const number=cleanCardText(problem||""),body=cleanCardText(front);return number&&body?`${number} ${body}`:body||number||"（内容なし）"}
function wordTarget(c:WordCard,data:AppData):ReviewTarget{const l=data.wordLists.find(x=>x.id===c.list_id)!,front=cleanCardText(c.front),back=cleanCardText(c.back),frontIds=[...(c.front_media_ids||[]),...mediaIdsFromText(c.front,l)],backIds=[...(c.back_media_ids||[]),...mediaIdsFromText(c.back,l)],title=fallbackCardText(c.card_id,front),context=cleanCardText(c.memo)||"カード";return{id:c.id,target_type:"word",group_id:l.id,group_title:l.title,context,title,card_id:c.card_id,front,back,memo:c.memo,state:c.state||empty,front_media_ids:[...new Set(frontIds)],back_media_ids:[...new Set(backIds)]}}
function materialContext(node:MaterialNode,nodes:MaterialNode[]){const titles:string[]=[];let parent=node.parent_id;while(parent){const current=nodes.find(n=>n.id===parent);if(!current)break;titles.unshift(current.title);parent=current.parent_id}return titles.join(" / ")}
function allTargets(data:AppData){const ownerId=data.profile?.id;return[...data.materialDecks.filter(deck=>deck.user_id===ownerId&&!deck.deleted_at).flatMap(deck=>orderedMaterialTargets(data,deck.id)),...data.wordLists.filter(list=>list.user_id===ownerId&&!list.deleted_at).flatMap(list=>orderedWordTargets(data,list.id))]}
function studentTargets(data:AppData,studentId:string){return[...data.materialDecks.filter(d=>d.user_id===studentId&&!d.deleted_at).flatMap(deck=>orderedMaterialTargets(data,deck.id)),...data.wordLists.filter(l=>l.user_id===studentId&&!l.deleted_at).flatMap(list=>orderedWordTargets(data,list.id))]}
function studentDeckOptions(data:AppData,studentId:string){return[...data.materialDecks.filter(d=>d.user_id===studentId&&!d.deleted_at).map(d=>[`material:${d.id}`,d.title]as const),...data.wordLists.filter(l=>l.user_id===studentId&&!l.deleted_at).map(l=>[`word:${l.id}`,l.title]as const)]}
function deckLabel(options:readonly(readonly[string,string])[],key:string){return options.find(([id])=>id===key)?.[1]||""}
async function dataWithDeckContent(data:AppData,deckKey:string){const[type,id]=deckKey.split(":")as[TargetType,string];if(type==="material"){const current=data.materialNodes.filter(n=>n.deck_id===id),expected=data.materialDecks.find(deck=>deck.id===id)?.item_count||0,loadedItems=current.filter(n=>n.node_type==="item").length;if(expected>0&&loadedItems>=expected)return data;const nodes=await loadMaterialNodes(id),count=nodes.filter(n=>n.node_type==="item").length;if(expected>0&&count===0)throw new Error(`DB上は${expected}問のデッキですが、問題を取得できませんでした。material_nodes の deck_id と RLS を確認してください。`);return{...data,materialNodes:[...data.materialNodes.filter(n=>n.deck_id!==id),...nodes],materialDecks:data.materialDecks.map(deck=>deck.id===id?{...deck,item_count:count}:deck)}}const current=data.wordCards.filter(card=>card.list_id===id),expected=data.wordLists.find(list=>list.id===id)?.item_count||0;if(expected>0&&current.length>=expected)return data;const cards=await loadWordCards(id);if(expected>0&&cards.length===0)throw new Error(`DB上は${expected}枚のデッキですが、カードを取得できませんでした。word_cards の list_id と RLS を確認してください。`);return{...data,wordCards:[...data.wordCards.filter(card=>card.list_id!==id),...cards],wordLists:data.wordLists.map(list=>list.id===id?{...list,item_count:cards.length}:list)}}
async function dataWithAssignmentContent(data:AppData,items:Pick<AssignmentItem,"target_type"|"target_id">[]){const loaded=await loadContentForAssignmentItems(items),nodeDecks=new Set(loaded.nodes.map(n=>n.deck_id)),cardLists=new Set(loaded.cards.map(c=>c.list_id));return{...data,materialNodes:[...data.materialNodes.filter(n=>!nodeDecks.has(n.deck_id)),...loaded.nodes],wordCards:[...data.wordCards.filter(c=>!cardLists.has(c.list_id)),...loaded.cards],materialDecks:data.materialDecks.map(deck=>nodeDecks.has(deck.id)?{...deck,item_count:loaded.nodes.filter(n=>n.deck_id===deck.id&&n.node_type==="item").length}:deck),wordLists:data.wordLists.map(list=>cardLists.has(list.id)?{...list,item_count:loaded.cards.filter(c=>c.list_id===list.id).length}:list)}}
function mergeLoadedContent(previous:AppData,fresh:AppData):AppData{const freshDeckIds=new Set(fresh.materialDecks.filter(deck=>!deck.deleted_at).map(deck=>deck.id)),freshListIds=new Set(fresh.wordLists.filter(list=>!list.deleted_at).map(list=>list.id)),loadedDeckIds=new Set(previous.materialDecks.filter(deck=>freshDeckIds.has(deck.id)&&(deck.item_count||0)>0&&previous.materialNodes.filter(n=>n.deck_id===deck.id&&n.node_type==="item").length>=(deck.item_count||0)).map(deck=>deck.id)),loadedListIds=new Set(previous.wordLists.filter(list=>freshListIds.has(list.id)&&(list.item_count||0)>0&&previous.wordCards.filter(card=>card.list_id===list.id).length>=(list.item_count||0)).map(list=>list.id)),freshNodes=new Map(fresh.materialNodes.map(node=>[node.id,node])),freshCards=new Map(fresh.wordCards.map(card=>[card.id,card]));return{...fresh,materialNodes:[...fresh.materialNodes.filter(node=>!loadedDeckIds.has(node.deck_id)),...previous.materialNodes.filter(node=>loadedDeckIds.has(node.deck_id)).map(node=>freshNodes.has(node.id)?{...node,...freshNodes.get(node.id)!}:node)],wordCards:[...fresh.wordCards.filter(card=>!loadedListIds.has(card.list_id)),...previous.wordCards.filter(card=>loadedListIds.has(card.list_id)).map(card=>freshCards.has(card.id)?{...card,...freshCards.get(card.id)!}:card)]}}
function assignmentDeckKey(data:AppData,assignment:Assignment,items:AssignmentItem[]){if(assignment.deck_type&&assignment.deck_id)return`${assignment.deck_type}:${assignment.deck_id}`;const target=items.map(item=>targetByAssignmentItem(data,item)).find(Boolean);return target?`${target.target_type}:${target.group_id}`:""}
function assignmentDeckName(data:AppData,assignment:Assignment,items:AssignmentItem[]){const key=assignmentDeckKey(data,assignment,items);if(!key)return"対象デッキ未読込";const[type,id]=key.split(":")as[TargetType,string];return type==="material"?data.materialDecks.find(d=>d.id===id)?.title||"デッキ":data.wordLists.find(l=>l.id===id)?.title||"デッキ"}
function assignmentDisplayTitle(data:AppData,assignment:Assignment,items:AssignmentItem[]){const deckName=assignmentDeckName(data,assignment,items);return deckName==="対象デッキ未読込"?assignment.title:deckName}
function targetByAssignmentItem(data:AppData,item:{target_type:"material_item"|"word_card";target_id:string}){return item.target_type==="material_item"?data.materialNodes.find(n=>n.id===item.target_id&&n.node_type==="item")&&materialTarget(data.materialNodes.find(n=>n.id===item.target_id)!,data):data.wordCards.find(c=>c.id===item.target_id)&&wordTarget(data.wordCards.find(c=>c.id===item.target_id)!,data)}
function targetByPlanItem(data:AppData,item:{target_type:"material_item"|"word_card";target_id:string}){return targetByAssignmentItem(data,item)}
function activePlanIds(data:AppData,userId?:string){return new Set(data.studyPlans.filter(plan=>(!userId||plan.user_id===userId)&&(plan.deck_type==="material"?data.materialDecks.some(deck=>deck.id===plan.deck_id&&!deck.deleted_at):data.wordLists.some(list=>list.id===plan.deck_id&&!list.deleted_at))).map(plan=>plan.id))}
function scheduledTargets(data:AppData,date:string){const plans=activePlanIds(data);return sortTargetsGlobal(data.studyPlanItems.filter(i=>plans.has(i.plan_id)&&i.scheduled_date===date&&i.status==="planned").map(i=>targetByPlanItem(data,i)).filter(Boolean)as ReviewTarget[])}
function scheduledTargetsForUser(data:AppData,date:string,userId:string){const plans=activePlanIds(data,userId);return sortTargetsGlobal(data.studyPlanItems.filter(i=>plans.has(i.plan_id)&&i.scheduled_date===date&&i.status==="planned").map(i=>targetByPlanItem(data,i)).filter(Boolean)as ReviewTarget[])}
function datesBetween(start:string,end:string){const out:string[]=[],a=new Date(`${start}T00:00:00`),b=new Date(`${end}T00:00:00`);for(let d=a;d<=b;d.setDate(d.getDate()+1))out.push(localDate(new Date(d)));return out.length?out:[start]}
function distributePlanItems(targets:ReviewTarget[],dates:string[],fallbackDate:string){const days=dates.length?dates:[fallbackDate],total=targets.length,base=Math.floor(total/days.length),extra=total%days.length,items:{target_type:"material_item"|"word_card";target_id:string;scheduled_date:string}[]=[];let cursor=0;days.forEach((date,index)=>{const count=base+(index<extra?1:0);targets.slice(cursor,cursor+count).forEach(target=>items.push({target_type:target.target_type==="material"?"material_item":"word_card",target_id:target.id,scheduled_date:date}));cursor+=count});return items}
function viewerDataForStudent(data:AppData,student:Profile):AppData{return{...data,profile:{...student,role:"student"},userTitles:data.userTitles.filter(t=>t.user_id===student.id),materialDecks:data.materialDecks.filter(d=>d.user_id===student.id),wordLists:data.wordLists.filter(l=>l.user_id===student.id),studyPlans:data.studyPlans.filter(p=>p.user_id===student.id),teacherLinks:data.teacherLinks.filter(l=>l.student_id===student.id||l.teacher_id===student.id),assignments:data.assignments.filter(a=>a.student_id===student.id),expTransactions:data.expTransactions.filter(e=>e.user_id===student.id),studySessions:data.studySessions.filter(s=>s.user_id===student.id),materialAttempts:data.materialAttempts.filter(a=>a.user_id===student.id),wordAttempts:data.wordAttempts.filter(a=>a.user_id===student.id)}}
function sortNodes(nodes:MaterialNode[]){return[...nodes].sort((a,b)=>{if(a.node_type==="folder"&&b.node_type==="folder"){const byTitle=naturalKey(a.title).localeCompare(naturalKey(b.title),"ja");if(byTitle)return byTitle}return a.order_index-b.order_index||naturalKey(a.title).localeCompare(naturalKey(b.title),"ja")})}
function orderedMaterialTargets(data:AppData,deckId:string){const nodes=data.materialNodes.filter(n=>n.deck_id===deckId),out:ReviewTarget[]=[];const walk=(parent:string|null)=>sortNodes(nodes.filter(n=>n.parent_id===parent)).forEach(node=>{if(node.node_type==="item")out.push(materialTarget(node,data));else walk(node.id)});walk(null);return out}
function sortCards(a:WordCard,b:WordCard){return a.order_index-b.order_index||naturalKey(a.card_id||a.front).localeCompare(naturalKey(b.card_id||b.front),"ja")}
function orderedWordTargets(data:AppData,listId:string){return data.wordCards.filter(c=>c.list_id===listId).sort(sortCards).map(c=>wordTarget(c,data))}
function sortTargetsForPlan(data:AppData,type:TargetType,deckId:string,targets:ReviewTarget[]){const ordered=type==="material"?orderedMaterialTargets(data,deckId):orderedWordTargets(data,deckId),rank=new Map(ordered.map((target,index)=>[target.id,index]));return[...targets].sort((a,b)=>(rank.get(a.id)??999999)-(rank.get(b.id)??999999)||naturalKey(a.title).localeCompare(naturalKey(b.title),"ja"))}
function sortTargetsGlobal(targets:ReviewTarget[]){return[...targets].sort((a,b)=>a.group_title.localeCompare(b.group_title,"ja")||naturalKey(a.context||"").localeCompare(naturalKey(b.context||""),"ja")||naturalKey(a.card_id||a.title).localeCompare(naturalKey(b.card_id||b.title),"ja"))}
function naturalKey(value:string){const normalized=value.trim().normalize("NFKC").toUpperCase(),mathRank:Record<string,string>={I:"01",A:"02",II:"03",B:"04",III:"05",C:"06"};if(mathRank[normalized])return`math-${mathRank[normalized]}`;const roman:Record<string,string>={Ⅰ:"1",Ⅱ:"2",Ⅲ:"3",Ⅳ:"4",Ⅴ:"5",Ⅵ:"6",Ⅶ:"7",Ⅷ:"8",Ⅸ:"9",Ⅹ:"10",I:"1",II:"2",III:"3",IV:"4",V:"5",VI:"6",VII:"7",VIII:"8",IX:"9",X:"10"};return value.replace(/[ⅠⅡⅢⅣⅤⅥⅦⅧⅨⅩ]|IV|VIII|VII|VI|III|II|IX|X|V|I/g,m=>roman[m]||m).replace(/\d+/g,m=>m.padStart(8,"0"))}
function descendants(id:string,nodes:MaterialNode[]){const ids=new Set([id]);let changed=true;while(changed){changed=false;nodes.forEach(n=>{if(n.parent_id&&ids.has(n.parent_id)&&!ids.has(n.id)){ids.add(n.id);changed=true}})}return ids}
function groupTargets(targets:ReviewTarget[]):[string,ReviewTarget[]][]{const groups=new Map<string,ReviewTarget[]>();targets.forEach(target=>{const key=`${target.target_type}:${target.group_id}`,items=groups.get(key)||[];items.push(target);groups.set(key,items)});return[...groups.entries()]}
type DailyLearning={date:string;total:number;material:number;cards:number;reviews:number;sessions:number;minutes:number;materialDecks:string[];cardDecks:string[]};
function learningDays(data:AppData){const result:DailyLearning[]=[],map=new Map<string,DailyLearning>(),userId=data.profile?.id,base=new Date();base.setHours(0,0,0,0);for(let offset=89;offset>=0;offset--){const value=new Date(base);value.setDate(base.getDate()-offset);const date=localDate(value),day={date,total:0,material:0,cards:0,reviews:0,sessions:0,minutes:0,materialDecks:[],cardDecks:[]};result.push(day);map.set(date,day)}const addDeck=(day:DailyLearning|undefined,name:string|undefined,type:"material"|"cards")=>{if(!day||!name)return;const target=type==="material"?day.materialDecks:day.cardDecks;if(!target.includes(name))target.push(name)};data.materialAttempts.filter(item=>item.user_id===userId&&item.rating).forEach(item=>{const day=map.get(localDate(new Date(item.reviewed_at)));if(!day)return;day.material++;day.total++;const node=data.materialNodes.find(n=>n.id===item.material_node_id);addDeck(day,data.materialDecks.find(deck=>deck.id===node?.deck_id)?.title,"material")});data.wordAttempts.filter(item=>item.user_id===userId&&item.rating).forEach(item=>{const day=map.get(localDate(new Date(item.reviewed_at)));if(!day)return;day.cards++;day.total++;const card=data.wordCards.find(c=>c.id===item.word_card_id);addDeck(day,data.wordLists.find(list=>list.id===card?.list_id)?.title,"cards")});data.expTransactions.filter(item=>item.user_id===userId&&item.reason==="review_complete").forEach(item=>{const day=map.get(localDate(new Date(item.created_at)));if(day){day.reviews++;day.total++}});data.studySessions.filter(item=>item.user_id===userId).forEach(item=>{const day=map.get(localDate(new Date(item.started_at)));if(!day)return;day.sessions++;day.total++;day.minutes+=item.duration_minutes||0;if(item.related_type==="material_deck")addDeck(day,data.materialDecks.find(deck=>deck.id===item.related_id)?.title,"material");else addDeck(day,data.wordLists.find(list=>list.id===item.related_id)?.title,"cards")});return result}
function learningStreak(days:DailyLearning[]){const todayActive=Boolean(days.at(-1)?.total),index=todayActive?days.length-1:days.length-2;let count=0;for(let i=index;i>=0&&days[i]?.total;i--)count++;return{count,label:todayActive?`連続 ${count}日`:count?`昨日まで${count}日連続`:"連続 0日"}}
function heatLevel(total:number){return total===0?0:total<=5?1:total<=20?2:3}
function localDate(date:Date){return`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`}
function formatDate(date:string){const[y,m,d]=date.split("-");return`${y}/${Number(m)}/${Number(d)}`}
